inlineScript.scriptBlock:
//Get Address BIC list On Load
this.getBicCodesOnLoad = function () {
	var cif = this.ui.get("collectingBankID").getData();
	if (cif != "" && cif != null) {
		this.ui.get("GetAddressBIC").execute(cif);
	}
};

//On retrieve cif info btn - service call to retrieve party info
this.getPartyDetails = function (cif, name) {
	this.context.options.partyTypeName.set("value", name);

	var customerCIF = this.ui.get(cif).getData();
	//validate cif before using it
	if (isNaN(Number(customerCIF)) || customerCIF.length < 8) {
		this.ui.get(cif).setValid(false, "CIF must be 8 Digits");
	} else {
		this.ui.get(cif).setValid(true);
		this.ui.get("GetPartyDetails").execute(customerCIF);
	}
};

//on load - set the vis of the 3 optional party types
this.onLoadSectionVis = function () {
	var collectingCif = this.ui.get("collectingBankCIF").getData();
	var accounteeCif = this.ui.get("partyCIF").getData();
	var caseCif = this.ui.get("partyCIF1").getData();
	var isChecker = this.context.options.isChecker.get("value");

	if (collectingCif) {
		this.ui.get("collectingBankSection").setVisible(true, true);
		this.ui.get("collectingBankSection").setEnabled(!isChecker);
	} else {
		//		this.ui.get("collectingBankSection").setVisible(false, true);
	}

	if (accounteeCif) {
		this.ui.get("partyTypesSection").setVisible(true, true);
		this.ui.get("partyTypesSection").setEnabled(!isChecker);
	} else {
		this.ui.get("partyTypesSection").setVisible(false, true);
	}

	if (caseCif) {
		
		this.ui.get("caseInNeedSection").setVisible(true, true);
		this.ui.get("caseInNeedSection").setEnabled(!isChecker);
	} else {
		//		this.ui.get("caseInNeedSection").setVisible(false, true);
	}

	// Amend visiblity controller
	var isAmend = this.context.options.requestType.get("value").toLowerCase().includes("amend") || false;
	var isChecker = this.context.options.isChecker.get("value") || false;

	// Drawer
	this.ui.get("drawerId").setEnabled(!isChecker && !isAmend);
	this.ui.get("Horizontal_Layout1").setEnabled(!isChecker);

	// collecting
	this.ui.get("Horizontal_Layout4").setVisible(!isAmend && !isChecker, true);
	this.ui.get("collectingBankSection").setEnabled(!isChecker);
	this.ui.get("collectingBankID").setEnabled(!isChecker && !isAmend);

	// case in need
	this.ui.get("Horizontal_Layout3").setVisible(!isAmend && !isChecker, true);
	var CIFNotEmpty = !!this.context.binding.get("value").get("caseInNeed").get("partyCIF");
	this.ui.get("caseInNeedSection").setEnabled(!isChecker && CIFNotEmpty);
	
	this.ui.get("partyId1").setEnabled(!isChecker && !isAmend);

	// Drawee
	this.ui.get("Horizontal_Layout2").setEnabled(!isChecker);
	this.ui.get("draweeID").setEnabled(!isChecker && !isAmend);
};

//on GetPartyDetails results - map the retrieved data
this.mapPartyData = function (name) {
	if (name == "collectingBank" && this.context.options.customerFullDetails.get("value").get("customerType") != "B") {
		var cif = "collectingBankCIF";
		this.ui.get(cif).setValid(false, "This CIF is not corresponding to a Bank");
	} else if (name == "collectingBank") {
		var bankCIF = this.context.options.customerFullDetails.get("value").get("customerNo");
		this.context.binding.get("value").get(name).set("id", bankCIF);

		this.context.binding.get("value").get(name).set("address1", this.context.options.customerFullDetails.get("value").get("customerAddress").get("addressLine1"));
		this.context.binding.get("value").get(name).set("address2", this.context.options.customerFullDetails.get("value").get("customerAddress").get("addressLine2"));
		this.context.binding.get("value").get(name).set("address3", this.context.options.customerFullDetails.get("value").get("customerAddress").get("addressLine3"));

		this.context.binding.get("value").get(name).set("name", this.context.options.customerFullDetails.get("value").get("customerName"));

		this.context.binding.get("value").get(name).set("country", this.context.options.customerFullDetails.get("value").get("nationality"));
		this.context.binding.get("value").get(name).set("language", "ENG");

		this.context.binding.get("value").get(name).set("reference", this.context.options.collectingBankReference.get("value"));
		this.context.binding.get("value").get(name).set("media", "SWIFT");

		this.ui.get("collectingBankSection").setVisible(true, true);
		//Service call to get Address code list
		this.ui.get("GetAddressBIC").execute(bankCIF);
	} else {
		this.context.binding.get("value").get(name).set("partyId", this.context.options.customerFullDetails.get("value").get("customerNo"));

		this.context.binding.get("value").get(name).set("address1", this.context.options.customerFullDetails.get("value").get("customerAddress").get("addressLine1"));
		this.context.binding.get("value").get(name).set("address2", this.context.options.customerFullDetails.get("value").get("customerAddress").get("addressLine2"));
		this.context.binding.get("value").get(name).set("address3", this.context.options.customerFullDetails.get("value").get("customerAddress").get("addressLine3"));

		this.context.binding.get("value").get(name).set("partyName", this.context.options.customerFullDetails.get("value").get("customerName"));

		this.context.binding.get("value").get(name).set("country", this.context.options.customerFullDetails.get("value").get("nationality"));
		this.context.binding.get("value").get(name).set("language", "ENG");
		this.context.binding.get("value").get(name).set("refrence", "NO REF");

		if (name == "partyTypes") this.ui.get("partyTypesSection").setVisible(true, true);

		if (name == "caseInNeed") {
			this.ui.get("caseInNeedSection").setVisible(true, true);
		}
		//Hidden btn to get Customer And Party Account List for charges - also its called on view load!!!
		this.ui.get("GetCustomerAndPartyAccountListBtn").click();
	}
};

//On change of cif field - reset party info
this.resetPartyOnCifChange = function (name) {
	if (name == "collectingBank") {
		this.context.binding.get("value").get(name).set("id", "");
		this.context.binding.get("value").get(name).set("address1", "");
		this.context.binding.get("value").get(name).set("address2", "");
		this.context.binding.get("value").get(name).set("address3", "");
		this.context.binding.get("value").get(name).set("name", "");
		this.context.binding.get("value").get(name).set("country", "");
		this.context.binding.get("value").get(name).set("language", "");
		this.context.binding.get("value").get(name).set("reference", "");
		this.context.binding.get("value").get(name).set("media", "");
		this.context.options.addressBICList.set("value", []);
	} else {
		this.context.binding.get("value").get(name).set("partyId", "");
		this.context.binding.get("value").get(name).set("address1", "");
		this.context.binding.get("value").get(name).set("address2", "");
		this.context.binding.get("value").get(name).set("address3", "");
		this.context.binding.get("value").get(name).set("partyName", "");
		this.context.binding.get("value").get(name).set("country", "");
		this.context.binding.get("value").get(name).set("language", "");
		this.context.binding.get("value").get(name).set("refrence", "");
	}
};

this.validateCIF = function (value) {
	var cifData = value.getData();
	if (cifData && cifData.length < 8) {
		value.setValid(false, "CIF must be 8 digits");
		return false;
	} else if (cifData && isNaN(Number(cifData))) {
		value.setValid(false, "CIF must be digits");
		//		value.setData("");
		return false;
	} else {
		value.setValid(true);
		return true;
	}
};
//++++++++++++++++++++++++++++++++++++++++++++++Error Handling+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
this.AjaxErrorHandling = function (errorMSG) {
	this.context.options.alertMessage.set("value", errorMSG);
	this.context.options.errorVis.set("value", "EDITABLE");
};
